typedef struct AVLNode {
    int value, height;
    struct AVLNode* left;
    struct AVLNode* right;
} AVLNode;

int balanceFactor(AVLNode* n) {
    if (!n) return 0;
    return height(n->left) - height(n->right);
}

AVLNode* rotateRight(AVLNode* y) {
    AVLNode* x = y->left;
    AVLNode* T2 = x->right;
    x->right = y;
    y->left = T2;
    return x; // x is the new subtree root
}

